// HALF_LIFE_DAYS controls time-decay weighting. In production, replace the
// "Generate journeys" node with a Webhook that receives real page/form/click
// touches; keep the rest of the pipeline as-is.
return [{ json: {
  HALF_LIFE_DAYS: 7,
  CHANNELS: ['paid_search', 'paid_social', 'organic', 'email', 'referral', 'direct'],
  N_VISITORS: 40,     // synthetic visitors for the demo run
} }];

// DEMO ONLY: generate synthetic multi-touch journeys. Each visitor has 2-4
// touches across channels over ~14 days; some visitors share an email (to prove
// identity stitching), and converting journeys carry revenue on the last touch.
// In production, delete this node and feed real touches from a Webhook instead.
const cfg = $json;
const CH = cfg.CHANNELS;
const pick = (a) => a[Math.floor(Math.random() * a.length)];
const now = Date.now();
const touches = [];
const emails = ['user@example.com', 'user@example.com', 'user@example.com', 'user@example.com', 'user@example.com'];

for (let v = 0; v < cfg.N_VISITORS; v++) {
  const vid = 'demo-' + v;
  const n = 2 + Math.floor(Math.random() * 3);
  const converts = Math.random() < 0.45;
  // ~30% of journeys resolve to a shared known email (identity stitching)
  const email = Math.random() < 0.3 ? pick(emails) : null;
  for (let i = 0; i < n; i++) {
    const daysAgo = (n - i) * (1 + Math.floor(Math.random() * 4));
    const last = i === n - 1;
    touches.push({
      visitor_id: vid,
      email: last ? email : (Math.random() < 0.4 ? email : null),
      channel: pick(CH),
      ts: new Date(now - daysAgo * 864e5).toISOString(),
      is_conversion: last && converts,
      revenue: last && converts ? 50 + Math.floor(Math.random() * 250) : 0,
    });
  }
}
return [{ json: { ...cfg, touches } }];

// Compute channel credit under four attribution models across converting
// journeys, weighted by revenue.
const cfg = $json;
const HL = cfg.HALF_LIFE_DAYS;
const models = { first_touch: {}, last_touch: {}, linear: {}, time_decay: {} };
const add = (m, ch, v) => { m[ch] = (m[ch] || 0) + v; };

let convJourneys = 0, revenue = 0;
for (const j of cfg.journeys) {
  if (!j.converted) continue;
  convJourneys++; revenue += j.revenue;
  const t = j.touches;
  const rev = j.revenue;
  add(models.first_touch, t[0].channel, rev);
  add(models.last_touch, t[t.length - 1].channel, rev);
  t.forEach((x) => add(models.linear, x.channel, rev / t.length));
  // time decay: weight by 2^(-daysBeforeConversion / half_life), normalized
  const w = t.map((x) => Math.pow(2, -((j.convTs - new Date(x.ts).getTime()) / 864e5) / HL));
  const wSum = w.reduce((n, x) => n + x, 0) || 1;
  t.forEach((x, i) => add(models.time_decay, x.channel, rev * (w[i] / wSum)));
}
const round = (o) => Object.fromEntries(Object.entries(o).map(([k, v]) => [k, +v.toFixed(2)]));
return [{ json: { channels: cfg.CHANNELS, models: { first_touch: round(models.first_touch), last_touch: round(models.last_touch), linear: round(models.linear), time_decay: round(models.time_decay) }, convJourneys, revenue: +revenue.toFixed(2), visitorsMerged: cfg.visitorsMerged } }];

// Print the attribution comparison across all four models.
const m = $json;
const chans = [...new Set([].concat(...Object.values(m.models).map((o) => Object.keys(o))))].sort();
const pad = (s, n) => String(s).padStart(n);

const out = [];
out.push('');
out.push('==========================================================');
out.push('  MULTI-TOUCH ATTRIBUTION ENGINE  |  nocode.expert');
out.push('==========================================================');
out.push('Converting journeys: ' + m.convJourneys + '   Revenue: $' + m.revenue.toLocaleString() + '   Identities merged by email: ' + m.visitorsMerged);
out.push('');
out.push('Channel'.padEnd(14) + pad('First', 10) + pad('Last', 10) + pad('Linear', 10) + pad('TimeDecay', 12));
out.push('-'.repeat(56));
for (const c of chans) {
  out.push(c.padEnd(14) + pad('$' + (m.models.first_touch[c] || 0), 10) + pad('$' + (m.models.last_touch[c] || 0), 10) + pad('$' + (m.models.linear[c] || 0), 10) + pad('$' + (m.models.time_decay[c] || 0), 12));
}
out.push('==========================================================');
console.log(out.join('\n'));
return [{ json: m }];

// Split the generated touch batch into one item per row so the Supabase
// 'Create a row' node inserts them one by one (native per-item execution).
return $('Generate synthetic multi-touch journeys (replace with Webhook)').first().json.touches.map(t => ({ json: t }));

// Stitch identity: visitor_ids that share an email are merged into one person,
// their touches combined and time-ordered. Pure data transform over Supabase rows.
const cfg = $('Set config: channels, time-decay half-life').first().json;
const rows = $input.all().map(i => i.json);
const byVisitor = {};
for (const r of rows) (byVisitor[r.visitor_id] = byVisitor[r.visitor_id] || []).push(r);
const emailOf = {};
for (const r of rows) if (r.email) emailOf[r.visitor_id] = r.email;
const people = {};
for (const [vid, ts] of Object.entries(byVisitor)) { const identity = emailOf[vid] || vid; (people[identity] = people[identity] || []).push(...ts); }
const journeys = Object.entries(people).map(([identity, ts]) => {
  ts.sort((a, b) => new Date(a.ts) - new Date(b.ts));
  const conv = ts.find((t) => t.is_conversion);
  return { identity, touches: ts, converted: !!conv, revenue: conv ? Number(conv.revenue) : 0, convTs: conv ? new Date(conv.ts).getTime() : null };
});
return [{ json: { CHANNELS: cfg.CHANNELS, HALF_LIFE_DAYS: cfg.HALF_LIFE_DAYS, journeys, visitorsMerged: Object.keys(byVisitor).length - Object.keys(people).length } }];
